import{_ as o,c as e,o as i,a2 as r}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Introducción","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md","lastUpdated":1793163976000}'),n={name:"es/guide/introduction.md"};function s(t,a,c,l,d,p){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to &quot;Introducción&quot;">​</a></h1><h2 id="acerca-de-nuezip" tabindex="-1">Acerca de NueZip <a class="header-anchor" href="#acerca-de-nuezip" aria-label="Permalink to &quot;Acerca de NueZip&quot;">​</a></h2><p>NueZip es un gestor de archivos profesional para macOS, diseñado para la velocidad, la fiabilidad y la facilidad de uso. Ya necesites comprimir archivos, extraer archivos comprimidos, convertir formatos o gestionar archivos protegidos con contraseña, NueZip lo hace todo con una experiencia nativa de macOS.</p><p>Construido con Swift 6 y SwiftUI, NueZip aprovecha al máximo Apple Silicon y las tecnologías de macOS para ofrecer una herramienta de gestión de archivos rápida, ligera y segura.</p><h2 id="funciones-principales" tabindex="-1">Funciones principales <a class="header-anchor" href="#funciones-principales" aria-label="Permalink to &quot;Funciones principales&quot;">​</a></h2><h3 id="📦-compatibilidad-con-multiples-formatos" tabindex="-1">📦 <strong>Compatibilidad con múltiples formatos</strong> <a class="header-anchor" href="#📦-compatibilidad-con-multiples-formatos" aria-label="Permalink to &quot;📦 **Compatibilidad con múltiples formatos**&quot;">​</a></h3><p>NueZip es compatible con todos los formatos de archivo principales:</p><ul><li><strong>RAR</strong> — Solo lectura con soporte multi-volumen</li><li><strong>ZIP</strong> — Compresión universal con cifrado AES</li><li><strong>7-Zip</strong> — Alta relación de compresión con LZMA2</li><li><strong>TAR</strong> — Agrupación de archivos con GZIP/BZIP2 opcionales</li><li><strong>GZIP / BZIP2</strong> — Formatos de compresión independientes</li></ul><h3 id="⚡-extraccion-rapida" tabindex="-1">⚡ <strong>Extracción rápida</strong> <a class="header-anchor" href="#⚡-extraccion-rapida" aria-label="Permalink to &quot;⚡ **Extracción rápida**&quot;">​</a></h3><p>La arquitectura de doble motor selecciona el backend óptimo para cada formato, garantizando las velocidades de extracción más rápidas posibles.</p><h3 id="🔐-proteccion-y-cifrado-con-contrasena" tabindex="-1">🔐 <strong>Protección y cifrado con contraseña</strong> <a class="header-anchor" href="#🔐-proteccion-y-cifrado-con-contrasena" aria-label="Permalink to &quot;🔐 **Protección y cifrado con contraseña**&quot;">​</a></h3><p>Crea archivos protegidos con contraseña con cifrado estándar de la industria. El gestor de contraseñas integrado almacena las credenciales de forma segura en tu cadena de claves local.</p><h3 id="📋-operaciones-por-lotes" tabindex="-1">📋 <strong>Operaciones por lotes</strong> <a class="header-anchor" href="#📋-operaciones-por-lotes" aria-label="Permalink to &quot;📋 **Operaciones por lotes**&quot;">​</a></h3><p>Procesa varios archivos a la vez:</p><ul><li><strong>Compresión por lotes</strong> — Comprime varios elementos en archivos individuales</li><li><strong>Extracción por lotes</strong> — Extrae varios archivos simultáneamente</li><li><strong>Conversión por lotes</strong> — Convierte archivos entre formatos de forma masiva</li><li><strong>Cifrado por lotes</strong> — Aplica protección con contraseña a varios archivos</li></ul><h3 id="🛠️-herramientas-avanzadas" tabindex="-1">🛠️ <strong>Herramientas avanzadas</strong> <a class="header-anchor" href="#🛠️-herramientas-avanzadas" aria-label="Permalink to &quot;🛠️ **Herramientas avanzadas**&quot;">​</a></h3><ul><li><strong>Reparación de archivos</strong> — Repara archivos RAR y ZIP corruptos</li><li><strong>Conversión de formato</strong> — Convierte entre cualquiera de los formatos compatibles</li><li><strong>Prueba de rendimiento</strong> — Prueba la velocidad y la calificación de compresión</li><li><strong>Búsqueda en archivos</strong> — Encuentra archivos dentro de los archivos por nombre</li><li><strong>Visor de información de archivos</strong> — Consulta metadatos detallados de las entradas del archivo</li><li><strong>Soporte de volúmenes/división</strong> — Crea archivos multi-volumen</li></ul><h3 id="🖥️-experiencia-nativa-de-macos" tabindex="-1">🖥️ <strong>Experiencia nativa de macOS</strong> <a class="header-anchor" href="#🖥️-experiencia-nativa-de-macos" aria-label="Permalink to &quot;🖥️ **Experiencia nativa de macOS**&quot;">​</a></h3><ul><li><strong>Swift 6 + SwiftUI</strong> — Interfaz moderna y receptiva</li><li><strong>Nativo en Apple Silicon</strong> — Optimizado para chips de la serie M</li><li><strong>Integración con Finder</strong> — Extensión de menú contextual con clic derecho</li><li><strong>Arrastrar y soltar</strong> — Acceso rápido mediante el panel de la barra de menú</li><li><strong>Uso mínimo de recursos</strong> — Funcionamiento ligero en segundo plano</li></ul><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del sistema&quot;">​</a></h2><ul><li><strong>Sistema operativo</strong>: macOS 14 Sonoma o posterior</li><li><strong>CPU</strong>: Apple Silicon (serie M) o Intel (64 bits)</li><li><strong>Memoria</strong>: 4 GB de RAM mínimo, 8 GB recomendado</li><li><strong>Almacenamiento</strong>: ~50 MB para la instalación</li></ul><h2 id="idiomas-compatibles" tabindex="-1">Idiomas compatibles <a class="header-anchor" href="#idiomas-compatibles" aria-label="Permalink to &quot;Idiomas compatibles&quot;">​</a></h2><p>NueZip es compatible con inglés, chino (simplificado), chino (tradicional), japonés, coreano y muchos otros idiomas.</p><h2 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h2><p>Si eres nuevo en NueZip, comienza con la <a href="/es/guide/installation.html">Guía de instalación</a> para poner la aplicación en funcionamiento en tu Mac.</p>',25)])])}const h=o(n,[["render",s]]);export{u as __pageData,h as default};
